<?php
namespace App\Http\Controllers\API;
use App\Http\Controllers\Controller; use App\Http\Resources\PayrollRecordResource; use App\Models\PayrollPeriod; use App\Models\PayrollRecord; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse;
class PayrollController extends Controller { public function index(Request $r) { $items=PayrollRecord::with(['staff','period'])->where('owner_id',$r->user()->id)->latest()->paginate(20); return PayrollRecordResource::collection($items)->response(); } public function store(Request $r): JsonResponse { $d=$r->validate(['name'=>['required','string','max:100'],'start_date'=>['required','date'],'end_date'=>['required','date','after_or_equal:start_date'],'staff_id'=>['required','exists:staff,id'],'basic_salary'=>['required','numeric','min:0'],'allowances'=>['nullable','numeric','min:0'],'deductions'=>['nullable','numeric','min:0']]);$r->user()->staff()->findOrFail($d['staff_id']);$period=PayrollPeriod::create(['owner_id'=>$r->user()->id,'name'=>$d['name'],'start_date'=>$d['start_date'],'end_date'=>$d['end_date']]);$record=PayrollRecord::create(['owner_id'=>$r->user()->id,'payroll_period_id'=>$period->id,'staff_id'=>$d['staff_id'],'basic_salary'=>$d['basic_salary'],'allowances'=>$d['allowances']??0,'deductions'=>$d['deductions']??0,'net_salary'=>($d['basic_salary']+($d['allowances']??0)-($d['deductions']??0))]);return response()->json(new PayrollRecordResource($record->load(['staff','period'])),201); } }
